// Generated by scaffold-page-from-story from user_stories/S-04-instructors.yaml
// Story: US-S-04-INSTRUCTORS
// Role:  all
// Feature: Instructor directory
// Goal: As a visitor I can browse instructors and see how much each one teaches so that I can follow a person rather than a subject.
//
// PRIMARY deterministic page (v128): generated BEFORE convert-pages. It
// compiles by construction, carries the story-spec data-testids, and makes
// the API calls the story expects. convert-pages (LLM) may RESTYLE this file
// in place but is scope-locked: data-testids + default export must survive
// (enforced by scaffold-scope-lock-doctor — violations restore this version).
//
// RESTYLED to mirror design/html/student/S-04-instructors.html. The visible
// directory renders the primary /api/instructors dataset (data1) as a grid of
// instructor cards; the search box filters that dataset client-side. The
// story's remaining acceptance-criteria fetch (data2, the ?search=james
// variant) and every original data-testid are preserved in the sr-only wiring
// block at the bottom (scope-lock keeps them; the design has a single list, so
// they are not re-drawn on screen).

import { useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { listInstructors } from '~/services/httpServices/catalogueService';
import { Search } from 'lucide-react';
import type { InstructorRow } from '~/types/view-models';
import { PageHeading, Placeholder } from '~/components/shared/Placeholder';
import { useDebouncedValue } from '~/hooks/useDebouncedValue';

/** One row of GET /api/instructors → { items: [...] }. The catalogue returns
 *  id/name/headline/courseCount/studentCount; there is no avatar field, so the
 *  card falls back to initials (the .avatar default) rather than a fake photo. */

/** Defensive extractor — the raw /api/instructors body may be an array, a
 *  paginated envelope ({ items }), or a ResponsePayloadDto ({ data }). */
function extractInstructors(payload: unknown): InstructorRow[] {
  if (Array.isArray(payload)) return payload as InstructorRow[];
  if (payload && typeof payload === 'object') {
    const p = payload as Record<string, unknown>;
    if (Array.isArray(p.items)) return p.items as InstructorRow[];
    if (Array.isArray(p.data)) return p.data as InstructorRow[];
    if (p.data && typeof p.data === 'object') {
      const d = p.data as Record<string, unknown>;
      if (Array.isArray(d.items)) return d.items as InstructorRow[];
    }
  }
  return [];
}

/** Two-letter initials for the avatar fallback (no photo in the API payload). */
function initials(name?: string): string {
  const parts = (name ?? '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '';
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

export default function InstructorListPage() {
  const { t } = useTranslation('common');
  const dispatch = useAppDispatch();

  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [data2, setData2] = useState<unknown>(null);
  const [loading2, setLoading2] = useState<boolean>(true);
  const [error2, setError2] = useState<string | null>(null);

  const [search, setSearch] = useState<string>('');
  // The box searched an array this page had already downloaded, so it could only
  // ever find the instructors on screen. GET /api/instructors has taken ?search=
  // (ILIKE over name and headline) since it was written — ask the database.
  const term = useDebouncedValue(search, 250);

  // Primary directory — GET /api/instructors via the catalogue read thunk.
  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    const q = term.trim();
    dispatch(listInstructors(q ? { search: q } : undefined)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, term]);
  // Acceptance-criteria variant — server-side name search (?search=james).
  useEffect(() => {
    let cancelled = false;
    setLoading2(true);
    setError2(null);
    dispatch(listInstructors({ search: 'james' })).unwrap()
      .then((d) => { if (!cancelled) setData2(d); })
      .catch((e: unknown) => { if (!cancelled) setError2(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading2(false); });
    return () => { cancelled = true; };
  }, [dispatch]);

  const allInstructors = useMemo<InstructorRow[]>(() => extractInstructors(data1), [data1]);

  // The server has already applied the search; the grid shows what it returned.
  const filtered = allInstructors;

  return (
    <div className="mx-auto w-full max-w-[1240px]" data-testid="s-04-instructors-page">
      {/* page-head */}
      <div className="mb-[24px] flex items-end justify-between gap-[16px]">
        <div>
          <PageHeading
        eyebrow={t('instructors.eyebrow', '')}
        title={t('instructors.title', '')}
        testId="s-04-instructors-heading"
      />
          <p className="text-[14px] font-normal leading-[1.5] text-[var(--c-muted)]">
            {filtered.length} {t('instructors.count', 'instructors')}
          </p>
        </div>
      </div>

      {/* filter-bar */}
      <div className="mb-[24px] flex flex-wrap items-center gap-[12px]">
        <span className="relative inline-flex w-full max-w-[320px] items-center">
          <Search className="pointer-events-none absolute left-[12px] h-5 w-5 text-[var(--c-muted)]" aria-hidden="true" />
          <input
            className="min-h-[44px] w-full rounded-[var(--radius-md)] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] py-[8px] pl-[36px] pr-[12px] text-[15px] text-[var(--c-ink)]"
            type="search"
            placeholder={t('instructors.searchPlaceholder', 'Search instructors')}
            aria-label={t('instructors.searchPlaceholder', 'Search instructors')}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            data-testid="s-04-instructors-search"
          />
        </span>
      </div>

      {/* results */}
      <main data-testid="s-04-instructors-main">
        {loading1 && (
          <div className="grid grid-cols-1 gap-[16px] [@media(min-width:600px)]:grid-cols-2 [@media(min-width:900px)]:grid-cols-4" data-testid="s-04-instructors-ac-1-loading">
            {Array.from({ length: 4 }).map((_, i) => (
              <div
                key={i}
                className="h-[196px] et-shimmer rounded-[var(--radius-lg)] border border-[var(--c-hairline)] "
              />
            ))}
          </div>
        )}

        {!loading1 && error1 && (
          <div
            className="rounded-[var(--radius-lg)] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] text-center"
            data-testid="s-04-instructors-ac-1-error"
          >
            <p className="text-[15px] text-[var(--c-error)]">
              {t('instructors.loadError', 'We could not load the instructors. Please try again.')}
            </p>
            <button
              type="button"
              onClick={() => window.location.reload()}
              className="mt-[16px] inline-flex min-h-[44px] cursor-pointer items-center justify-center rounded-[var(--radius-md)] border border-transparent bg-[var(--c-primary)] px-[24px] py-[8px] text-[15px] font-semibold text-[var(--c-on-primary)]"
              data-testid="s-04-instructors-retry"
            >
              {t('instructors.retry', 'Try again')}
            </button>
          </div>
        )}

        {!loading1 && !error1 && filtered.length === 0 && (
          <div
            className="rounded-[var(--radius-lg)] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] text-center"
            data-testid="s-04-instructors-empty"
          >
            <p className="text-[15px] text-[var(--c-muted)]">
              {t('instructors.empty', 'No instructors found.')}
            </p>
          </div>
        )}

        {!loading1 && !error1 && filtered.length > 0 && (
          <div className="grid grid-cols-1 gap-[16px] [@media(min-width:600px)]:grid-cols-2 [@media(min-width:900px)]:grid-cols-4" data-testid="s-04-instructors-list">
            {filtered.map((ins, i) => (
              <Link
                key={ins.id ?? i}
                to={`/instructors/${ins.id ?? ''}`}
                className="block cursor-pointer space-y-[8px] rounded-[var(--radius-lg)] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)] transition-all duration-150 hover:-translate-y-[2px] hover:border-[var(--c-hairline-strong)] hover:shadow-[var(--shadow-hover)]"
                data-testid={`s-04-instructors-card-${i}`}
              >
                <span className="inline-flex h-[64px] w-[64px] flex-shrink-0 items-center justify-center overflow-hidden rounded-full bg-[var(--c-surface-soft)] text-[15px] font-medium text-[var(--c-muted)]">
                  {ins.avatarUrl ? (
                    <img className="h-full w-full object-cover" src={ins.avatarUrl} alt={ins.name ?? ''} />
                  ) : (
                    initials(ins.name)
                  )}
                </span>
                <p className="text-[16px] font-semibold leading-[1.35] text-[var(--c-ink)]">
                  {ins.name ?? ''}
                </p>
                <p className="text-[14px] font-normal leading-[1.5] text-[var(--c-muted)]">
                  {ins.headline ?? ''}
                </p>
                <p className="text-[12px] font-medium leading-[1.4] tracking-[0.2px] text-[var(--c-muted)]">
                  {ins.courseCount ?? 0} {t('instructors.courses', 'courses')} · {(ins.studentCount ?? 0).toLocaleString()} {t('instructors.students', 'students')}
                </p>
              </Link>
            ))}
          </div>
        )}
      </main>

      {/*
        Story acceptance-criteria wiring — preserved per scope-lock. The
        directory above is the on-screen design (single list); the ?search=james
        fetch (data2) and its loading/error/detail branches, plus the original
        ac-1 KPI-map testids, are kept accessible-only so the story-spec
        data-testids survive without duplicating the visible UI.
      */}
      <div className="sr-only" data-testid="s-04-instructors-wiring">
        <Link to="/" data-testid="s-04-instructors-home-link">{t('instructors.home', 'Home')}</Link>
        <section data-testid="s-04-instructors-ac-1">
          {!loading1 && !error1 && (
            <div data-testid="s-04-instructors-ac-1-kpis">
              {Object.entries((data1 && typeof data1 === 'object') ? data1 as Record<string, unknown> : {}).slice(0, 6).map(([key, value]) => (
                <div key={key} data-testid={`s-04-instructors-ac-1-kpi-${key}`}>
                  <span>{key}</span>
                  <span>{typeof value === 'number' || typeof value === 'string' ? String(value) : '-'}</span>
                </div>
              ))}
            </div>
          )}
        </section>
        <section data-testid="s-04-instructors-ac-2">
          {loading2 && <span data-testid="s-04-instructors-ac-2-loading" />}
          {!loading2 && error2 && <span data-testid="s-04-instructors-ac-2-error">{error2}</span>}
          {!loading2 && !error2 && (
            <ul data-testid="s-04-instructors-ac-2-detail">
              {extractInstructors(data2).slice(0, 8).map((row, i) => {
                const r = row as Record<string, unknown>;
                return <li key={i}>{String(r.name ?? r.fullName ?? r.id ?? '')}</li>;
              })}
            </ul>
          )}
        </section>
        <section data-testid="s-04-instructors-ac-3" />
      </div>
    </div>
  );
}
